      item.setAttribute("aria-label", `Ver foto ${i + 1} de Mateo y Carol en grande`);
      const img = document.createElement("img");
      img.src = src;
      img.alt = `Foto ${i + 1} de Mateo y Carol`;
      img.loading = i === 0 ? "eager" : "lazy";
      img.decoding = "async";
